<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import {stagingSession} from '../integrations/firebase/stagingSession'
import {isStagingMode,mayWriteLive} from '../integrations/firebase/stagingConfig'
import {watchGymIdentity,saveGymIdentity,emptyIdentity} from '../integrations/firestore/platform'
import {accountKey} from '../features/platform/platformModel'
import {compressIdentity} from '../features/platform/identityImage'
const p=defineProps<{edit?:boolean;compact?:boolean}>()
const identity=ref(emptyIdentity()),draft=ref(emptyIdentity()),ready=ref(false),dirty=ref(false),busy=ref(false),message=ref(''),readError=ref(false)
let stop:(()=>void)|undefined,epoch=0
watch(()=>accountKey(stagingSession.value),()=>{const s=stagingSession.value;stop?.();const n=++epoch;identity.value=emptyIdentity();draft.value=emptyIdentity();ready.value=false;dirty.value=false;readError.value=false;message.value='';if(!isStagingMode()||!s||p.edit&&s.role!=='titolare')return;stop=watchGymIdentity(s,v=>{if(n!==epoch)return;identity.value=v;ready.value=true;if(!dirty.value)draft.value={...v}},()=>{if(n!==epoch)return;readError.value=true;message.value='Identità non completamente leggibile: verifica le regole Firestore.'})},{immediate:true})
onUnmounted(()=>{epoch++;stop?.()})
async function pick(e:Event,kind:'logo'|'cover'){const el=e.target as HTMLInputElement,file=el.files?.[0];el.value='';if(!file||busy.value)return;const n=epoch;busy.value=true;message.value='';try{const data=await compressIdentity(file,kind);if(n===epoch){draft.value={...draft.value,[kind]:data};dirty.value=true}}catch(e){if(n===epoch)message.value=(e as Error).message}finally{if(n===epoch)busy.value=false}}
async function save(){if(busy.value||!ready.value||readError.value||!dirty.value)return;busy.value=true;message.value='';try{await saveGymIdentity({...draft.value},accountKey(stagingSession.value));dirty.value=false;message.value='Identità salvata.'}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
 <section v-if="edit&&stagingSession?.role==='titolare'" class="panel lf14-identity-editor"><h2>Identità palestra</h2><p class="muted small">Nome, logo e foto di copertina visibili solo agli utenti della tua palestra.</p><p v-if="!ready" class="muted">Caricamento identità…</p><template v-else><label>Nome palestra<input v-model="draft.name" maxlength="100" @input="dirty=true" :disabled="busy||readError"/></label><div class="lf14-brand-fields"><label>Logo palestra<img v-if="draft.logo" :src="draft.logo" alt="Anteprima logo" class="lf14-logo"/><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy||readError" @change="pick($event,'logo')"/><button v-if="draft.logo" class="secondary" type="button" :disabled="busy" @click="draft.logo='';dirty=true">Rimuovi logo</button></label><label>Foto di copertina<img v-if="draft.cover" :src="draft.cover" alt="Anteprima copertina" class="lf14-cover-preview"/><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy||readError" @change="pick($event,'cover')"/><button v-if="draft.cover" class="secondary" type="button" :disabled="busy" @click="draft.cover='';dirty=true">Rimuovi foto</button></label></div><button class="primary wide" :disabled="busy||!dirty||readError||!mayWriteLive()" @click="save">{{busy?'Attendi…':'Salva identità palestra'}}</button></template><p v-if="message" class="notice" role="status">{{message}}</p></section>
 <section v-else-if="!edit&&(identity.name||compact)" class="lf14-gym-identity" :class="{'lf14-with-cover':!!identity.cover,'lf14-compact':compact}"><img v-if="identity.cover" :src="identity.cover" alt="" class="lf14-bg-cover"/><div class="lf14-gym-label"><img :src="identity.logo||'/v1-preview/LOGO-APP.png'" class="lf14-logo" alt="Logo palestra"/><div><small>{{identity.name?'PALESTRA':'PANNELLO COACH'}}</small><strong>{{identity.name||'LionFit'}}</strong></div></div></section>
</template>
